/*
 * Who Drew These Lines? Australia. One map that changes with the chapter being read.
 * Data: window.GEO (data/geo.js, generated by build/build.py) and window.CONTENT (js/content.js).
 */
(() => {
  const G = window.GEO, C = window.CONTENT;
  // Translation: the English text is the key (a js/lang-xx.js can fill window.LANG_DICT); {name} fills values
  const DICT = window.LANG_DICT || {};
  const T = (s, vars = {}) => (DICT[s] ?? s).replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  const $ = s => document.querySelector(s);
  const NS = "http://www.w3.org/2000/svg";
  const el = (tag, attrs = {}, parent) => {
    const n = document.createElementNS(NS, tag);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    if (parent) parent.append(n);
    return n;
  };
  const html = (tag, attrs = {}, text) => {
    const n = document.createElement(tag);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    if (text != null) n.textContent = text;
    return n;
  };
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

  // ---------------------------------------------------------------- Projection (same as build/geo.py)
  const P = G.proj, D2R = Math.PI / 180, L0 = P.lon0 * D2R, F0 = P.lat0 * D2R;
  function proj(lon, lat) {
    const l = lon * D2R, f = lat * D2R;
    const k = Math.sqrt(2 / (1 + Math.sin(F0) * Math.sin(f) + Math.cos(F0) * Math.cos(f) * Math.cos(l - L0)));
    const x = P.k * k * Math.cos(f) * Math.sin(l - L0);
    const y = P.k * k * (Math.cos(F0) * Math.sin(f) - Math.sin(F0) * Math.cos(f) * Math.cos(l - L0));
    return [x - P.ox, -y - P.oy];
  }

  // ---------------------------------------------------------------- Colours: one per colony, for its whole life
  const FAM = {
    nsw: "#7fb2d9", vic: "#4f73b5", qld: "#b04a6a", sa: "#d4574a", wa: "#f2c94c", tas: "#5f9e6e",
    nt: "#d9783f", na: "#c9a26b", act: "#8a5fa8"
  };
  const COUNTRY_FILL = "#d79a5b";
  const CAT_LABEL = { none: "Not claimed by Britain", colony: "British colony", part: "Part of a colony", state: "State",
    territory: "Territory governed by the Commonwealth", selfgov: "Self-governing territory" };

  function bbox(d) {
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    for (const m of d.matchAll(/(-?[\d.]+),(-?[\d.]+)/g)) {
      const x = +m[1], y = +m[2];
      if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y;
    }
    return [x0, y0, x1, y1];
  }

  // ---------------------------------------------------------------- Map skeleton
  const svg = $("#map");
  svg.setAttribute("viewBox", G.viewBox.join(" "));
  // the part of the frame that must always be seen: Australia and the Torres Strait
  const CONTENT_BOX = (() => { const a = bbox(G.land); return [a[0] - 10, a[1] - 14, a[2] + 10, a[3] + 8]; })();
  function fitMap() {
    const bw = svg.clientWidth, bh = svg.clientHeight;
    if (!bw || !bh) return;
    const top = 46, bottom = (legend.offsetHeight || 0) + 14;
    const [x0, y0, x1, y1] = CONTENT_BOX, W = x1 - x0, H = y1 - y0;
    const avail = Math.max(60, bh - top - bottom);
    const s = Math.min(bw / W, avail / H);
    const vw = bw / s, vh = bh / s;
    const vx = x0 - (vw - W) / 2, vy = y0 - top / s - (avail / s - H) / 2;
    svg.setAttribute("viewBox", [vx, vy, vw, vh].map(v => v.toFixed(1)).join(" "));
    // keep names inside the visible map
    for (const t of [...L.labels.querySelectorAll("text"), ...names.querySelectorAll("text")]) {
      const x = +(t.dataset.x ??= t.getAttribute("x")), w = t.getBBox().width;
      const lo = vx + w / 2 + 6, hi = vx + vw - w / 2 - 6;
      if (lo < hi) t.setAttribute("x", Math.min(hi, Math.max(lo, x)).toFixed(1));
    }
    for (const g of L.points.querySelectorAll(".pt")) {
      const c = g.querySelector("circle"), t = g.querySelector("text"), cx = +c.getAttribute("cx"), r = +c.getAttribute("r");
      const right = cx + r + 3 + t.getBBox().width > vx + vw - 4;
      t.setAttribute("x", right ? cx - r - 3 : cx + r + 3);
      t.setAttribute("text-anchor", right ? "end" : "start");
    }
  }
  const defs = el("defs", {}, svg);
  function hatch(id, color, bg = "none", w = 3, gap = 7) {
    const p = el("pattern", { id, patternUnits: "userSpaceOnUse", width: gap, height: gap, patternTransform: "rotate(45)" }, defs);
    if (bg !== "none") el("rect", { width: gap, height: gap, fill: bg }, p);
    el("rect", { width: w, height: gap, fill: color }, p);
    return `url(#${id})`;
  }
  const NONE_FILL = hatch("hatchNone", "#e2cfa9", "#f4ead6", 2, 8);
  const PART_FILL = hatch("hatchPart", FAM.sa, "#f6d3cc", 4, 9);
  const TERR = {};
  for (const f in FAM) TERR[f] = hatch(`terr-${f}`, FAM[f], "#fffaf0", 4.5, 8);

  el("rect", { x: -50, y: -50, width: G.viewBox[2] + 100, height: G.viewBox[3] + 100, class: "sea" }, svg);
  el("path", { d: G.context, class: "context" }, svg);
  const names = el("g", { "aria-hidden": "true" }, svg);
  for (const [n, [x, y]] of G.contextNames) el("text", { x, y, class: "context-name" }, names).textContent = T(n);
  for (const [n, [x, y]] of G.seaNames) el("text", { x, y, class: "sea-name" }, names).textContent = T(n);

  const layer = name => el("g", { class: `layer layer-${name}` }, svg);
  const L = { pieces: layer("pieces"), edges: layer("edges"), coast: layer("coast"), hl: layer("hl"), lines: layer("lines"),
    labels: layer("labels"), points: layer("points") };
  L.edges.classList.add("edges");
  L.pieces.classList.add("pieces");
  el("path", { d: G.land, class: "coast" }, L.coast);

  // ---------------------------------------------------------------- Pieces of today's land, and who they belonged to
  const pieceKeys = Object.keys(G.pieces);
  const piecePaths = {}, pieceDots = {};
  for (const k of pieceKeys) {
    const pc = G.pieces[k];
    if (pc.d) piecePaths[k] = el("path", { d: pc.d, class: "unit", "data-piece": k }, L.pieces);
    if (pc.dot) pieceDots[k] = el("circle", { cx: pc.l[0], cy: pc.l[1], r: 4.5, class: "unit dotunit", "data-piece": k }, L.pieces);
  }
  const edgePaths = G.edges.map(([a, b, d]) => ({ a, b, p: el("path", { d }, L.edges) }));
  function unitAt(piece, y) {
    let u = null;
    for (const [from, unit] of G.timeline[piece]) if (from <= y) u = unit;
    return u;
  }
  function fillFor(unit, mode) {
    const u = G.units[unit];
    if (mode === "country") return COUNTRY_FILL;
    if (u.c === "none") return NONE_FILL;
    if (u.c === "part") return PART_FILL;
    if (u.c === "territory") return TERR[u.f];
    return FAM[u.f];
  }
  const nameOf = unit => T(G.units[unit].n);
  function paintPieces(year, mode = "colonies") {
    for (const k of pieceKeys) {
      const unit = unitAt(k, year);
      for (const n of [piecePaths[k], pieceDots[k]]) {
        if (!n) continue;
        n.setAttribute("fill", fillFor(unit, mode));
        const f = fillFor(unit, mode);  // a stroke of the same colour hides the seams between pieces of one unit
        n.style.stroke = f.startsWith("#") ? f : "";
        n.dataset.tip = mode === "country" ? T("Aboriginal and Torres Strait Islander Country") : nameOf(unit);
        n.classList.toggle("ut", G.units[unit].c === "territory");
        n.classList.remove("faded");
      }
    }
    for (const e of edgePaths) e.p.style.display = mode !== "country" && unitAt(e.a, year) !== unitAt(e.b, year) ? "" : "none";
    if (mode === "country") L.labels.replaceChildren(); else labelPieces(year);
  }
  function fadePieces(on = true) {
    for (const n of [...Object.values(piecePaths), ...Object.values(pieceDots)]) n.classList.toggle("faded", on);
  }
  function labelPieces(year) {
    L.labels.replaceChildren();
    const byUnit = {};
    for (const k of pieceKeys) (byUnit[unitAt(k, year)] ||= []).push(G.pieces[k]);
    const minA = innerWidth < 900 ? 3000 : 1500;
    for (const u in byUnit) {
      const area = byUnit[u].reduce((s, p) => s + p.a, 0);
      if (area < minA) continue;
      const big = byUnit[u].reduce((a, b) => (b.a > a.a ? b : a));
      const name = G.units[u].c === "none" ? T("Not claimed by Britain") : nameOf(u).replace(/ \(.*\)$/, "");
      label(big.l[0], big.l[1], name, area > 40000 ? "big" : "small");
    }
  }
  function label(x, y, text, cls = "") {
    const t = el("text", { x, y, class: `lbl ${cls}` }, L.labels);
    t.textContent = text;
    return t;
  }
  function legendFor(year) {
    const seen = new Map();
    for (const k of pieceKeys) {
      const u = unitAt(k, year), un = G.units[u];
      const key = un.c === "none" ? "none" : u;
      if (!seen.has(key)) seen.set(key, [un.c === "none" ? "repeating-linear-gradient(45deg,#e2cfa9 0 2px,#f4ead6 2px 8px)" :
        un.c === "part" ? `repeating-linear-gradient(45deg,${FAM.sa} 0 4px,#f6d3cc 4px 9px)` :
        un.c === "territory" ? `repeating-linear-gradient(45deg,${FAM[un.f]} 0 4px,#fffaf0 4px 8px)` : FAM[un.f],
        un.c === "none" ? T("Not claimed by Britain") : nameOf(u)]);
    }
    setLegend([...seen.values()]);
  }

  // ---------------------------------------------------------------- Lines drawn across the continent
  function claimLine(key, cls = "", tag = "") {
    const p = el("path", { d: G.claims[key], class: `claim-line ${cls}` }, L.lines);
    if (tag) {
      const [x0, y0] = bbox(G.claims[key]);
      el("text", { x: x0, y: y0 - 8, class: "claim-tag" }, L.lines).textContent = tag;
    }
    return p;
  }
  const rulerPaths = {};
  function drawRuler() {
    for (const k in G.ruler) {
      rulerPaths[k] = el("path", { d: G.ruler[k].d, class: "ruler-line", "data-tip": `${T(G.ruler[k].n)}: ${T(G.ruler[k].t)}` }, L.lines);
      rulerPaths[k].addEventListener("click", () => pickRuler(k));
    }
    if (pickedRuler) pickRuler(pickedRuler);
  }

  // ---------------------------------------------------------------- Points
  const pointNodes = [];
  function addPoint(name, [x, y], color, tip, onClick, r = 6, key = name) {
    const g = el("g", { class: r >= 7 ? "pt cap" : "pt", "data-tip": tip, "data-key": key }, L.points);
    el("circle", { cx: x, cy: y, r, fill: color, "data-tip": tip }, g);
    const t = el("text", { x: x + r + 3, y: y + 5 }, g);
    t.textContent = name;
    if (onClick) g.addEventListener("click", e => { e.stopPropagation(); onClick(); });
    pointNodes.push(g);
    return g;
  }
  function showList(list, color, pick, withYear) {
    L.points.replaceChildren();
    pointNodes.length = 0;
    list.forEach((f, i) => {
      const tip = withYear ? `${T(f[0])} (${f[3]}): ${T(f[4])}` : `${T(f[0])}: ${T(f[3])}`;
      addPoint(T(f[0]), proj(f[1], f[2]), color, tip, pick ? () => pick(i) : null, 6.5);
    });
  }

  // ---------------------------------------------------------------- Legend, notes
  const legend = $("#mapLegend");
  const sw = (c, t) => `<span><i style="background:${c}"></i>${esc(t)}</span>`;
  function setLegend(items) { legend.innerHTML = items.map(([c, t]) => sw(c, t)).join(""); }
  const note = t => { $("#mapNote").textContent = t || ""; };

  // ---------------------------------------------------------------- Chapter states
  let state = null, year = 1788, timer = null;
  const STATES = {
    country() {
      $("#mapYear").textContent = T("Before 1788");
      paintPieces(1788, "country");
      showList(C.COUNTRY, "#2b2118", pickCountry);
      setLegend([[COUNTRY_FILL, T("Aboriginal and Torres Strait Islander Country: hundreds of nations")]]);
      note(T("The dots show only a few nations. There were hundreds."));
      if (C.COUNTRY.picked != null) pickCountry(C.COUNTRY.picked);
    },
    "1788"() {
      $("#mapYear").textContent = "1788";
      paintPieces(1788);
      claimLine("135E", "", "135° E");
      L.points.replaceChildren(); pointNodes.length = 0;
      C.FIRST.forEach(f => addPoint(T(f[0]), proj(f[1], f[2]), "#2b2118", `${T(f[0])}: ${T(f[3])}`, null, 6.5));
      legendFor(1788);
      note(T("The claim of 1788, as it was written in London."));
    },
    "1829"() {
      $("#mapYear").textContent = "1829";
      paintPieces(1829);
      claimLine("135E", "old"); claimLine("129E", "", "129° E");
      L.points.replaceChildren(); pointNodes.length = 0;
      C.WHOLE.forEach(f => addPoint(T(f[0]), proj(f[1], f[2]), "#2b2118", `${T(f[0])}: ${T(f[3])}`, null, 6.5));
      legendFor(1829);
      note(T("From 1825 to 1829."));
    },
    "1850"() {
      $("#mapYear").textContent = "1850";
      paintPieces(1850);
      L.points.replaceChildren(); pointNodes.length = 0;
      legendFor(1850);
      note(T("Colonies in 1850."));
      if (lastGuess) highlightPiece(lastGuess);
    },
    frontier() {
      $("#mapYear").textContent = "1790–1928";
      paintPieces(1850); fadePieces();
      L.labels.replaceChildren();
      showList(C.FRONTIER, "#c23b32", pickFrontier, true);
      setLegend([["#c23b32", T("Some places of the frontier wars")]]);
      note(T("Only a few places. There were many more."));
      if (C.FRONTIER.picked != null) pickFrontier(C.FRONTIER.picked);
    },
    "1863"() {
      $("#mapYear").textContent = "1863";
      paintPieces(1863);
      drawRuler();
      L.points.replaceChildren(); pointNodes.length = 0;
      legendFor(1863);
      note(T("The borders of 1863 are, almost exactly, the borders of today's states."));
    },
    "1901"() {
      $("#mapYear").textContent = "1901";
      paintPieces(1901);
      L.points.replaceChildren(); pointNodes.length = 0;
      legendFor(1901);
      note(T("The six states of 1901."));
    },
    "1911"() {
      $("#mapYear").textContent = "1911";
      paintPieces(1911);
      L.points.replaceChildren(); pointNodes.length = 0;
      addPoint(T("Canberra"), proj(149.13, -35.28), "#2b2118", T("Canberra, the new capital, built from 1913"), null, 7);
      addPoint(T("Melbourne"), proj(144.96, -37.81), "#2b2118", T("Melbourne: seat of the federal government until 1927"), null, 5.5);
      legendFor(1911);
      note(T("Hatched: territories governed by the Commonwealth."));
    },
    rights() {
      $("#mapYear").textContent = "1963–1996";
      paintPieces(2026); fadePieces();
      L.labels.replaceChildren();
      showList(C.RIGHTS, "#2b2118", pickRights, true);
      setLegend([["#2b2118", T("Places where people stood up for their Country")]]);
      note("");
      if (C.RIGHTS.picked != null) pickRights(C.RIGHTS.picked);
    },
    changes() {
      L.points.replaceChildren(); pointNodes.length = 0;
      paintYear(year);
      note(T("Each colony keeps its colour while its borders change."));
    },
    today() {
      $("#mapYear").textContent = T("Today");
      paintPieces(2026);
      L.points.replaceChildren(); pointNodes.length = 0;
      legendFor(2026);
      note(T("Mainland Australia and Tasmania. Small islands and external territories are not drawn."));
    }
  };

  function highlightPiece(piece) {
    L.hl.replaceChildren();
    const u = unitAt(piece, 1850);
    for (const k of pieceKeys) if (unitAt(k, 1850) === u && G.pieces[k].d) el("path", { d: G.pieces[k].d, class: "hl" }, L.hl);
  }

  function setState(name) {
    if (name === state) return;
    state = name;
    stopYears();
    L.labels.replaceChildren(); L.hl.replaceChildren(); L.lines.replaceChildren(); L.points.replaceChildren();
    pointNodes.length = 0;
    $("#mapHint").hidden = true;
    hideTip();
    STATES[name]();
    fitMap();
  }

  // ---------------------------------------------------------------- Tooltip
  const tip = $("#tip"), box = $("#mapBox");
  function hideTip() { tip.hidden = true; }
  function showTipAt(e, text) {
    const r = box.getBoundingClientRect();
    tip.textContent = text;
    tip.hidden = false;
    const x = Math.min(e.clientX - r.left + 12, r.width - tip.offsetWidth - 6);
    tip.style.left = `${Math.max(6, x)}px`;
    tip.style.top = `${Math.max(6, e.clientY - r.top - tip.offsetHeight - 10)}px`;
  }
  const tipOf = t => t.closest && (t.closest("[data-tip]")?.dataset.tip);
  svg.addEventListener("pointermove", e => { const t = tipOf(e.target); t ? showTipAt(e, t) : hideTip(); });
  svg.addEventListener("pointerleave", hideTip);
  svg.addEventListener("click", e => {
    if (!matchMedia("(hover: none)").matches) return;
    const t = tipOf(e.target);
    t ? showTipAt(e, t) : hideTip();
  });

  // ---------------------------------------------------------------- Chips + card (chapters 1, 5 and 9)
  // Each list remembers its choice, so that the map shows it again when the reader comes back to the chapter
  function chipList(list, target, card, mapState, withYear) {
    const pick = i => {
      list.picked = i;
      const f = list[i];
      document.querySelectorAll(`${target} button`).forEach((b, j) => b.setAttribute("aria-pressed", i === j));
      $(card).innerHTML = withYear ? `<b>${esc(T(f[0]))}, ${esc(f[3])}</b><br>${esc(T(f[4]))}` : `<b>${esc(T(f[0]))}</b> · ${esc(T(f[3]))}<br>${esc(T(f[4]))}`;
      if (state === mapState) pointNodes.forEach((g, j) => g.classList.toggle("on", i === j));
    };
    list.forEach((f, i) => {
      const b = html("button", { type: "button", "aria-pressed": "false" }, withYear ? `${T(f[0])} ${f[3]}` : T(f[0]));
      b.onclick = () => pick(i);
      $(target).append(b);
    });
    return pick;
  }
  const pickCountry = chipList(C.COUNTRY, "#countryChips", "#countryCard", "country", false);
  const pickFrontier = chipList(C.FRONTIER, "#frontierChips", "#frontierCard", "frontier", true);
  const pickRights = chipList(C.RIGHTS, "#rightsChips", "#rightsCard", "rights", true);

  // ---------------------------------------------------------------- Chapter 4: in 1850, which colony?
  let lastGuess = null;
  const placeBy = n => G.places.find(p => p.n === n);
  const shortName = u => nameOf(u).replace(/ \(.*\)$/, "");
  for (const [city, why] of C.GUESS) {
    const p = placeBy(city), answer = unitAt(p.piece, 1850);
    const row = html("div", { class: "guess-row" });
    row.append(html("b", {}, T(city)));
    const opts = html("span", { class: "opts" });
    const fb = html("span", { class: "fb", "aria-live": "polite" });
    for (const val of C.GUESS_OPTIONS) {
      const b = html("button", { type: "button" }, shortName(val));
      b.onclick = () => {
        if (row.classList.contains("done")) return;
        row.classList.add("done");
        b.classList.add(val === answer ? "ok" : "ko");
        fb.textContent = `${val === answer ? T("✅ Yes!") : T("❌ Not quite.")} ${T(why)}`;
        lastGuess = p.piece;
        if (state === "1850") highlightPiece(p.piece);
      };
      opts.append(b);
    }
    row.append(opts, fb);
    $("#guess").append(row);
  }

  // ---------------------------------------------------------------- Chapter 6: the ruler lines
  let pickedRuler = null;
  function pickRuler(k) {
    pickedRuler = k;
    document.querySelectorAll("#rulerChips button").forEach(b => b.setAttribute("aria-pressed", b.dataset.k === k));
    const r = G.ruler[k];
    $("#rulerCard").innerHTML = `<b>${esc(T(r.n))}</b> · ${T("about {km} km of border", { km: r.km.toLocaleString("en") })}<br>${esc(T(r.t))}`;
    for (const j in rulerPaths) rulerPaths[j].classList.toggle("on", j === k);
  }
  for (const k in G.ruler) {
    const b = html("button", { type: "button", "data-k": k, "aria-pressed": "false" }, T(G.ruler[k].n));
    b.onclick = () => pickRuler(k);
    $("#rulerChips").append(b);
  }

  // ---------------------------------------------------------------- Chapter 10: years slider
  const slider = $("#yearSlider");
  const LAST = +slider.max;
  function counts(y) {
    const us = new Set(pieceKeys.map(k => unitAt(k, y)));
    let col = 0, st = 0, te = 0;
    for (const u of us) {
      const c = G.units[u].c;
      if (c === "colony") col++; else if (c === "state") st++; else if (c === "territory" || c === "selfgov") te++;
    }
    return { col, st, te };
  }
  function paintYear(y) {
    year = y;
    slider.value = y;
    $("#yearNow").textContent = y;
    const n = counts(y);
    $("#yearCount").innerHTML = y < 1901 ? T("<b>{n}</b> British colonies", { n: n.col })
      : T("<b>{s}</b> states and <b>{t}</b> territories", { s: n.st, t: n.te });
    let m = G.milestones[0];
    for (const row of G.milestones) if (row[0] <= y) m = row;
    $("#yearCaption").textContent = `${m[0]}: ${T(m[1])}`;
    if (state !== "changes") return;
    $("#mapYear").textContent = y;
    paintPieces(y);
    legendFor(y);
    fitMap();
  }
  const MILE_YEARS = new Set(G.milestones.map(m => m[0]));
  function stopYears() { clearTimeout(timer); timer = null; $("#playYears").textContent = T("▶ Play"); }
  function stepYears() {
    if (year >= LAST) { stopYears(); return; }
    paintYear(year + 1);
    timer = setTimeout(stepYears, MILE_YEARS.has(year) ? 1500 : 70);
  }
  $("#playYears").onclick = () => {
    if (timer) { stopYears(); return; }
    if (state !== "changes") $("#cap10").scrollIntoView({ behavior: "smooth", block: "center" });
    if (year >= LAST) paintYear(1788);
    $("#playYears").textContent = T("⏸ Pause");
    timer = setTimeout(stepYears, 400);
  };
  slider.oninput = () => { stopYears(); paintYear(+slider.value); };
  paintYear(1788);

  // ---------------------------------------------------------------- Numbers in the text
  $("#pct1788").textContent = `${G.stats.claim_1788_pct}%`;
  $("#meter1788").style.setProperty("--w", `${G.stats.claim_1788_pct}%`);
  $("#pctStraight").textContent = `${G.stats.straight_pct}%`;
  $("#meterStraight").style.setProperty("--w", `${G.stats.straight_pct}%`);

  // ---------------------------------------------------------------- Map as a list (for screen readers and for printing)
  const firstYear = u => Math.min(...pieceKeys.flatMap(k => G.timeline[k].filter(([, v]) => v === u).map(([f]) => f)));
  function yearTable(y, target) {
    const us = [...new Set(pieceKeys.map(k => unitAt(k, y)))].sort((a, b) => nameOf(a).localeCompare(nameOf(b), "en"));
    const rows = us.map(u => `<tr><td>${esc(nameOf(u))}</td><td>${esc(T(CAT_LABEL[G.units[u].c]))}</td><td>${G.units[u].c === "none" ? "" : firstYear(u)}</td></tr>`).join("");
    $(target).innerHTML = `<div class="table-wrap"><table class="data-table"><thead><tr><th>${T("Name")}</th><th>${T("Kind")}</th><th>${T("Since")}</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }
  for (const [y, t] of [[1788, "#table-1788"], [1829, "#table-1829"], [1850, "#table-1850"], [1863, "#table-1863"], [1901, "#table-1901"], [1911, "#table-1911"], [2026, "#table-today"]]) yearTable(y, t);

  // ---------------------------------------------------------------- Chapters and scrolling
  const chapters = [...document.querySelectorAll(".chap")];
  function readingLine() {
    if (innerWidth >= 900) return innerHeight * 0.5;
    const mapBottom = $(".map-col").getBoundingClientRect().bottom;
    return mapBottom + (innerHeight - mapBottom) * 0.35;
  }
  function updateChapter() {
    const line = readingLine();
    let cur = chapters[0];
    for (const c of chapters) if (c.getBoundingClientRect().top < line) cur = c;
    chapters.forEach(c => c.classList.toggle("active", c === cur));
    setState(cur.dataset.map);
  }
  const bar = $("#progressBar");
  const onScroll = () => {
    const h = document.documentElement;
    bar.style.width = `${(h.scrollTop / Math.max(1, h.scrollHeight - h.clientHeight)) * 100}%`;
    updateChapter();
  };
  addEventListener("resize", () => { const s = state; state = null; setState(s); fitMap(); });
  addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  // ---------------------------------------------------------------- Your place through time
  const ROWS = [1788, 1829, 1850, 1863, 1901, 1911, 1927, 2026];
  const sel = $("#placeSel");
  G.places.slice().sort((a, b) => T(a.n).localeCompare(T(b.n), "en")).forEach(p => sel.append(html("option", { value: p.n }, `${T(p.n)} (${T(p.today)})`)));
  function showPlace(name) {
    const p = placeBy(name);
    const rows = [`<tr><th scope="row">${T("Always")}</th><td style="--c:${COUNTRY_FILL}">${esc(T(C.PLACE_COUNTRY[name] || ""))}<small>${esc(T("Country of the traditional owners"))}</small></td></tr>`];
    for (const y of ROWS) {
      const unit = unitAt(p.piece, y), u = G.units[unit];
      const color = u.c === "none" ? "#e2cfa9" : FAM[u.f];
      rows.push(`<tr><th scope="row">${y === 2026 ? T("Today") : y}</th><td style="--c:${color}">${esc(u.c === "none" ? T("Not claimed by Britain") : nameOf(unit))}<small>${esc(T(CAT_LABEL[u.c]))}</small></td></tr>`);
    }
    $("#placeTable tbody").innerHTML = rows.join("");
  }
  sel.onchange = () => showPlace(sel.value);
  sel.value = "Darwin";
  showPlace("Darwin");

  // ---------------------------------------------------------------- Name cards
  C.FLIPS.forEach(f => {
    const front = T("Before: {old}. Flip to see the name of today.", f), back = T("Now: {now}, since {y}. {why}", f);
    const b = html("button", { type: "button", class: "flip", "aria-pressed": "false", "aria-label": front });
    b.innerHTML = `<span class="flip-in"><span class="face front"><span class="ico" aria-hidden="true">${f.ico}</span><small>${T("It used to be")}</small><b>${esc(f.old)}</b><span class="turn" aria-hidden="true">${T("↻ flip")}</span></span><span class="face back"><small>${T("Since {y}", f)}</small><b>${esc(f.now)}</b><span>${esc(f.why)}</span></span></span>`;
    b.onclick = () => {
      const on = b.getAttribute("aria-pressed") !== "true";
      b.setAttribute("aria-pressed", on);
      b.setAttribute("aria-label", on ? back : front);
    };
    $("#flips").append(b);
  });

  // ---------------------------------------------------------------- Quiz
  const quiz = $("#quiz");
  let score = 0, answered = 0;
  function buildQuiz() {
    quiz.replaceChildren(); score = 0; answered = 0; $("#quizEnd").hidden = true;
    C.QUIZ.forEach((item, qi) => {
      const fs = html("fieldset", { class: "qz" });
      fs.append(html("legend", {}, `${qi + 1}. ${item.q}`));
      const opts = html("div", { class: "qz-opts" }), fb = html("p", { class: "qz-fb", "aria-live": "polite" });
      item.a.forEach((txt, ai) => {
        const b = html("button", { type: "button" }, txt);
        b.onclick = () => {
          if (fs.classList.contains("done")) return;
          fs.classList.add("done");
          const right = ai === item.ok;
          if (right) score++;
          b.classList.add(right ? "ok" : "ko");
          opts.children[item.ok].classList.add("ok");
          fb.textContent = `${right ? T("✅ Well done!") : T("❌ Not quite.")} ${item.why}`;
          if (++answered === C.QUIZ.length) finish();
        };
        opts.append(b);
      });
      fs.append(opts, fb);
      quiz.append(fs);
    });
  }
  function finish() {
    const medal = score === C.QUIZ.length ? "🏆" : score >= 5 ? "🏅" : "🌱";
    $("#quizScore").innerHTML = `${medal} ${T("You got <b>{n} out of {total}</b>!", { n: score, total: C.QUIZ.length })}`;
    $("#quizEnd").hidden = false;
  }
  $("#quizAgain").onclick = buildQuiz;
  buildQuiz();

  window.__app = { setState, paintYear, proj };
})();
